const { AdminService } = require("../services/adminService");

const ADMIN_EMAIL = (process.env.ADMIN_EMAIL || "").trim().toLowerCase();

/**
 * Middleware to authenticate Admin tokens
 * Checks bearer token generated by adminLogin
 */
async function authenticateAdminToken(req, res, next) {
  try {
    const authHeader = req.headers.authorization;
    const adminEmailHeader = (req.headers["x-admin-email"] || req.headers["x-admin-user"] || "").trim().toLowerCase();

    // 1. Direct check for configured ADMIN_EMAIL from environment
    if (ADMIN_EMAIL && adminEmailHeader === ADMIN_EMAIL) {
      const master = await AdminService.findByEmail(ADMIN_EMAIL).catch(() => null);
      if (master) {
        req.admin = master;
        return next();
      }
    }

    // 2. Token header validation
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({
        success: false,
        message: "Admin authorization token required (Bearer <token>)",
      });
    }

    const token = authHeader.split(" ")[1];

    if (!token || !token.startsWith("adm_token_")) {
      return res.status(401).json({
        success: false,
        message: "Invalid admin session token format",
      });
    }

    const encodedPart = token.replace("adm_token_", "");
    let decoded;
    try {
      decoded = Buffer.from(encodedPart, "base64").toString("utf8");
    } catch {
      return res.status(401).json({
        success: false,
        message: "Corrupted admin session token",
      });
    }

    const [adminId, email] = decoded.split(":");
    if (!adminId || !email) {
      return res.status(401).json({
        success: false,
        message: "Invalid session claims",
      });
    }

    const cleanEmail = email.trim().toLowerCase();

    // 3. Lookup administrator by ID or email from database
    let admin = await AdminService.findById(adminId).catch(() => null);
    if (!admin) {
      admin = await AdminService.findByEmail(cleanEmail).catch(() => null);
    }

    // 4. Check if token belongs to environment superadmin
    if (!admin && ADMIN_EMAIL && cleanEmail === ADMIN_EMAIL) {
      admin = {
        id: adminId || "admin-env-master",
        email: ADMIN_EMAIL,
        name: "Primary Administrator",
        role: "super_admin",
        permissions: ["all"],
      };
    }

    if (!admin) {
      return res.status(401).json({
        success: false,
        message: "Administrator account no longer exists or access was revoked",
      });
    }

    req.admin = admin;
    next();
  } catch (err) {
    console.error("authenticateAdminToken error:", err);
    return res.status(500).json({
      success: false,
      message: "Server error during admin authentication check",
      error: err.message,
    });
  }
}

module.exports = {
  authenticateAdminToken,
};
